/* Incremental journal layer. Original DATA and travel tools remain authoritative. */
'use strict';
const reduced=()=>matchMedia('(prefers-reduced-motion: reduce)').matches;
const journalTitle='北欧追光手记 | Nordic Journal 2026';
const journalDescription='挪威与冰岛的秋冬旅行，记录极光、鲸群、峡湾与冰川。';
let country='all';
const expandedDays=new Set();
const smallPhoto=k=>PHOTO_VARIANTS[pImage(k)]?.small||pImage(k);
const photoAttributes=src=>{const v=PHOTO_VARIANTS[src];return v?`srcset="${v.small} ${v.smallWidth}w, ${src} ${v.width}w" sizes="(max-width:760px) calc(100vw - 40px), 860px"`:'';};
const originalDay=renderDay,originalOverview=overview,originalRender=render;
const baseOpenDrawer=openDrawer;openDrawer=function(title,body){baseOpenDrawer(title,body);const im=$('.detail-photo img');if(im){im.tabIndex=0;im.setAttribute('role','button');im.setAttribute('aria-label','全屏查看'+im.alt);im.addEventListener('keydown',e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();im.click();}});}};
const representative=d=>(d.spots||[]).find(k=>pImage(k))||({1:'station',2:'tromso',8:'ballstad',9:'oslo',17:'station'})[d.id]||'';
function highlights(d){const names=(d.spots||[]).map(k=>DATA.places[k]?.name).filter(Boolean);return names.length?names.slice(0,4):(d.flights||[]).map(f=>`${f[0]} · ${f[2]} → ${f[5]}`).slice(0,4);}
function journeyIntro(){return `<section class="journey-intro route-overview"><button class="atlas-button" data-mapday="all" aria-label="打开全程互动路线地图">${atlas()}<span>查看路线地图 ↗</span></button></section>`;}
function journalCards(){const days=DATA.days.filter(d=>country==='all'?true:country==='transfer'?!['挪威','冰岛'].includes(d.region):d.region===country);return days.map(d=>{const k=representative(d),src=smallPhoto(k);return `<article class="journal-day" id="summary-${d.id}"><button data-day="${d.id}" class="journal-day-link" aria-label="查看${dateText(d.date)}${esc(d.title)}完整安排">${src?`<div class="journal-day-photo"><img src="${src}" alt="${esc(DATA.places[k]?.name||d.title)}" loading="lazy" decoding="async" width="720" height="480"></div>`:`<div class="transfer-photo"><span>${String(d.id).padStart(2,'0')}</span>${ico('plane')}</div>`}<div class="journal-day-copy"><p class="day-meta">${dateText(d.date)} · ${esc(d.region)}</p><h3>${esc(d.title)}</h3><p>${highlights(d).map(esc).join(' · ')||esc(d.alert)}</p><span class="read-day">查看当天安排 <span>↗</span></span></div></button></article>`;}).join('');}
function itineraryIndex(){return `<section class="itinerary-index" id="itinerary"><div class="index-heading"><div><p class="editor-label">逐日翻阅</p><h2>十八天的路书</h2></div><select class="quick-jump" aria-label="快速跳到旅行日期"><option value="">跳到日期</option>${DATA.days.map(d=>`<option value="${d.id}">${shortDate(d.date)} ${esc(d.title)}</option>`).join('')}</select></div><div class="segments country-segments" role="group" aria-label="按国家浏览">${[['all','全部'],['挪威','挪威'],['冰岛','冰岛'],['transfer','途经城市']].map(([k,n])=>`<button data-country="${k}" aria-pressed="${country===k}">${n}</button>`).join('')}</div><div class="journal-grid">${journalCards()}</div></section>`;}
function home(){return `<section class="journal-hero"><img src="${pImage('hamnoy')}" width="1176" height="805" alt="Hamnøy红屋与罗弗敦山海" fetchpriority="high" decoding="async"><div class="hero-copy"><p>2026.10.18 — 11.04 · 18天</p><h1>Nordic<br>Journal <em>2026</em></h1><p>挪威 · 冰岛<br>经赫尔辛基与哥本哈根</p><button class="hero-entry" data-enter>开始翻阅 ↓</button></div><span class="hero-caption">Hamnøy · Lofoten, Norway</span></section>${itineraryIndex()}<footer class="journal-footer"><span>Nordic Journal 2026</span><div><button data-credits>照片来源与许可</button><button data-share>分享路书</button><button data-top>回到顶部 ↑</button><a href="compat.html">无脚本阅读版 ↗</a></div></footer>`;}
overview=function(){return `<div class="view-top"><p class="editor-label">2026.10.18 — 11.04</p><h1>旅程概览</h1></div>${journeyIntro()}${itineraryIndex()}`;};
renderDay=function(){const d=DATA.days[state.day-1],k=representative(d),src=pImage(k),items=highlights(d);return `<section class="day-summary"><p class="day-meta">${dateText(d.date)} · ${esc(d.region)} <span>${String(d.id).padStart(2,'0')} / 18</span></p><h1>${esc(d.title)}</h1><p class="day-en">${esc(d.en)}</p>${src?`<button class="summary-image" data-photo="${k}" aria-label="全屏查看${esc(DATA.places[k]?.name)}"><img src="${src}" ${photoAttributes(src)} width="1200" height="800" alt="${esc(DATA.places[k]?.name)}" fetchpriority="high"><span>查看照片 ⤢</span></button>`:''}<p class="sun-summary">日出约 ${esc(d.sun[0])} · 日落约 ${esc(d.sun[1])} <span>${esc(d.tz)}</span></p><ul class="day-highlights">${items.map(n=>`<li>${esc(n)}</li>`).join('')}</ul>${d.alert?`<p class="summary-alert">${inline(d.alert)}</p>`:''}<div class="summary-actions"><button data-expand-day aria-expanded="${expandedDays.has(d.id)}" aria-controls="fullDay">${expandedDays.has(d.id)?'收起详细安排':'展开详细安排'} <span>⌄</span></button><button data-mapday="${d.id}">路线地图 ↗</button>${d.hotel?`<button data-hotel="${d.hotel}">今晚住宿 ↗</button>`:''}</div></section><div id="fullDay" class="day-collapse ${expandedDays.has(d.id)?'is-open':''}" ${expandedDays.has(d.id)?'':'inert'}><div class="day-collapse-inner"><div class="complete-day">${originalDay().replace(/<header class="page-header">[\s\S]*?<\/header>/,'')}</div></div></div>${`<div class="summary-pagination"><button data-day="${d.id-1}" ${d.id===1?'disabled':''}>← 前一天</button><button data-day="${d.id+1}" ${d.id===18?'disabled':''}>后一天 →</button></div>`}`;};
photoCard=(k,i)=>{const p=DATA.places[k],src=smallPhoto(k);return !p||!src?'':`<figure class="postcard"><button class="postcard-photo" data-photo="${k}" aria-label="全屏查看${esc(p.name)}"><img src="${src}" alt="${esc(p.name)}" loading="lazy" decoding="async" width="720" height="480"></button><figcaption class="postcard-footer"><button data-place="${k}">${esc(p.name)} <span>详情 ↗</span></button></figcaption></figure>`;};
/* Each segmented control owns one physical slider; layout is read only on target changes. */
const springs=new WeakMap();
function moveSlider(el){const buttons=[...el.querySelectorAll(':scope > button')];if(!buttons.length)return;let slider=el.querySelector(':scope > .segment-slider');if(!slider){slider=document.createElement('span');slider.className='segment-slider';slider.setAttribute('aria-hidden','true');el.prepend(slider);}const selected=buttons.find(b=>b.getAttribute('aria-pressed')==='true'||b.classList.contains('active'))||buttons[0];let s=springs.get(el);const target=selected.offsetLeft;slider.style.width=selected.offsetWidth+'px';if(!s){s={x:target,v:0,target,frame:0};springs.set(el,s);slider.style.transform=`translateX(${target}px)`;}s.target=target;if(reduced()){cancelAnimationFrame(s.frame);s.frame=0;s.x=target;s.v=0;slider.style.transform=`translateX(${target}px)`;return;}if(s.frame)return;let last=performance.now();function step(t){const dt=Math.min((t-last)/1000,.15);last=t;const alpha=22,omega=Math.sqrt(166),delta=s.x-s.target,co=Math.cos(omega*dt),si=Math.sin(omega*dt),decay=Math.exp(-alpha*dt),carry=(s.v+alpha*delta)/omega;s.x=s.target+decay*(delta*co+carry*si);s.v=decay*((-alpha*delta+omega*carry)*co+(-alpha*carry-omega*delta)*si);slider.style.transform=`translateX(${s.x}px)`;if(Math.abs(s.target-s.x)<.1&&Math.abs(s.v)<.15){s.x=s.target;slider.style.transform=`translateX(${s.x}px)`;s.frame=0;}else s.frame=requestAnimationFrame(step);}s.frame=requestAnimationFrame(step);}
function setupSegments(){document.querySelectorAll('.choice,.transport-grid,.segments,.bottom-nav').forEach(el=>{el.classList.add('shared-segments');moveSlider(el);});}
function parseRoute(){const h=location.hash.slice(1);if(/^day-\d+$/.test(h)){state.day=Math.min(18,Math.max(1,+h.slice(4)));state.view='day';}else if(/^map(?:-\d+)?$/.test(h)){state.view='map';mapFilter=h.includes('-')?h.split('-')[1]:'all';}else state.view=['home','overview','orders','memo'].includes(h)?h:'home';}
function routeHash(){return state.view==='day'?`day-${state.day}`:state.view==='map'&&mapFilter!=='all'?`map-${mapFilter}`:state.view;}
let navigatingHistory=false;
render=function(scroll=true){const nav=$('#bottomNav');let retained=nav.firstElementChild?nav.innerHTML:null;const liveNav=[...nav.childNodes];const transport=!scroll?$('.transport-grid'):null;const choice=!scroll?$('.choice'):null;if(state.view==='home'){if(map){map.remove();map=null;}$('#page').innerHTML=home();$('#dayRail').innerHTML='';}else originalRender(scroll);document.body.dataset.view=state.view;document.title=journalTitle;document.querySelector('.brand button').setAttribute('aria-current',state.view==='home'?'page':'false');if(!nav.dataset.journal){nav.innerHTML=[['home','首页','book'],['day','日程','calendar'],['overview','路线','map'],['orders','预订','ticket'],['memo','备忘','bag']].map(([k,n,i])=>`<button data-view="${k}">${ico(i)}<span>${n}</span></button>`).join('');nav.dataset.journal='true';}else if(retained){nav.replaceChildren(...liveNav);}nav.querySelectorAll('button').forEach(b=>{const active=b.dataset.view===state.view||(state.view==='map'&&b.dataset.view==='overview');b.classList.toggle('active',active);b.setAttribute('aria-current',active?'page':'false');});if(transport&&$('.transport-grid')){$('.transport-grid').replaceWith(transport);transport.querySelectorAll('button').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.transport===state.transport)));}if(choice&&$('.choice')){$('.choice').replaceWith(choice);choice.dataset.selected=state.variants[state.day]||'A';choice.querySelectorAll('button').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.variant===choice.dataset.selected)));}if(state.view==='day'){const rail=$('#dayRail');const jump=document.createElement('div');jump.className='rail-jump';jump.innerHTML=`<label>快速定位<select class="quick-jump" aria-label="跳到旅行日期">${[...new Set(DATA.days.map(d=>d.region))].map(region=>`<optgroup label="${region}">${DATA.days.filter(d=>d.region===region).map(d=>`<option value="${d.id}" ${state.day===d.id?'selected':''}>${shortDate(d.date)} ${esc(d.title)}</option>`).join('')}</optgroup>`).join('')}</select></label>`;rail.prepend(jump);}document.querySelectorAll('img').forEach(im=>{im.decoding='async';if(im.closest('.venue-thumb,.detail-photo'))im.style.aspectRatio='3 / 2';});if(scroll){window.scrollTo({top:0,behavior:'instant'});if(state.view!=='home')$('#page').focus({preventScroll:true});}const hash=routeHash();if(!navigatingHistory&&location.hash!=='#'+hash)history.pushState(null,'','#'+hash);persist();setupSegments();};
animateContent=function(el){if(!el||reduced())return;el.getAnimations().forEach(a=>a.cancel());el.animate([{opacity:.65,transform:'translateY(5px)'},{opacity:1,transform:'none'}],{duration:190,easing:'cubic-bezier(.2,0,0,1)'});};
window.addEventListener('popstate',()=>{navigatingHistory=true;parseRoute();render();navigatingHistory=false;});
window.addEventListener('resize',setupSegments,{passive:true});
matchMedia('(prefers-reduced-motion: reduce)').addEventListener?.('change',setupSegments);
async function copyLink(url){try{if(navigator.clipboard&&isSecureContext){await navigator.clipboard.writeText(url);toast('链接已复制');return;}}catch{}const ta=document.createElement('textarea');ta.value=url;ta.style.cssText='position:fixed;top:0;left:0;width:1px;height:1px;opacity:.01';document.body.append(ta);ta.focus();ta.select();let ok=false;try{ok=document.execCommand('copy');}catch{}ta.remove();if(ok)toast('链接已复制');else openDrawer('复制路书链接',`<p>长按下方链接复制</p><input class="share-url" readonly value="${esc(url)}" aria-label="路书链接">`);}
async function shareJournal(){const url=location.href;if(/MicroMessenger/i.test(navigator.userAgent)){openDrawer('分享路书',`<p class="detail-desc">点击微信右上角「…」，选择「发送给朋友」或「分享到朋友圈」。</p><p>可复制当前页面链接，保留已选日期。微信卡片展示由微信决定。</p><button class="primary-link" data-copy-link>复制当前链接</button>`);return;}if(navigator.share){try{await navigator.share({title:journalTitle,text:journalDescription,url});return;}catch(e){if(e.name==='AbortError')return;}}await copyLink(url);}
saveHtml=function(){const a=document.createElement('a');a.href='offline.html';a.download='北境路书_2026_完整离线版.html';a.click();toast('正在下载完整离线版；微信中请在浏览器打开后保存');};
const viewer=document.createElement('div');viewer.className='photo-viewer';viewer.hidden=true;viewer.setAttribute('role','dialog');viewer.setAttribute('aria-modal','true');viewer.setAttribute('aria-label','风景照片查看器');viewer.innerHTML='<div class="photo-toolbar"><span id="photoCounter"></span><button data-photo-close aria-label="关闭照片">关闭 ×</button></div><div class="photo-stage"><img alt="" draggable="false"></div><div class="photo-bottom"><button data-photo-prev aria-label="上一张照片">←</button><div><p id="photoCaption"></p><small>左右滑动切换 · 双击或双指缩放</small></div><button data-photo-next aria-label="下一张照片">→</button></div>';document.body.append(viewer);
let gallery=[],photoIndex=0,photoFocus=null,originRect=null,oldOverflow='',zoom=1;const photo=viewer.querySelector('img'),stage=viewer.querySelector('.photo-stage');
function photoAnimate(from,to){if(reduced())return;photo.getAnimations().forEach(a=>a.cancel());return photo.animate([{transform:from},{transform:to}],{duration:230,easing:'cubic-bezier(.2,0,0,1)'});}
function showPhoto(index,opening=false){photoIndex=(index+gallery.length)%gallery.length;const key=gallery[photoIndex];photo.src=pImage(key);photo.alt=DATA.places[key]?.name||CREDITS[key]?.title||'沿途风景';zoom=1;photo.style.transform='';stage.scrollTo(0,0);$('#photoCounter').textContent=`${photoIndex+1} / ${gallery.length}`;$('#photoCaption').textContent=photo.alt;photo.onload=()=>{if(opening&&originRect){const r=photo.getBoundingClientRect();photoAnimate(`translate(${originRect.x+originRect.width/2-r.x-r.width/2}px,${originRect.y+originRect.height/2-r.y-r.height/2}px) scale(${originRect.width/r.width},${originRect.height/r.height})`,'none');}else photoAnimate('translateX(12px)','none');};}
function openPhoto(key,source){photoFocus=document.activeElement;gallery=[...new Set([key,...[...document.querySelectorAll('[data-photo]')].map(x=>x.dataset.photo)])].filter(k=>pImage(k));originRect=source?.getBoundingClientRect();oldOverflow=document.body.style.overflow;viewer.hidden=false;document.body.style.overflow='hidden';for(const id of ['mainShell','bottomNav','topbar'])$('#'+id).inert=true;if($('#overlay').classList.contains('open'))$('#overlay').inert=true;showPhoto(0,true);viewer.querySelector('[data-photo-close]').focus({preventScroll:true});}
function closePhoto(){const finish=()=>{viewer.hidden=true;document.body.style.overflow=oldOverflow;const drawerOpen=$('#overlay').classList.contains('open');for(const id of ['mainShell','bottomNav','topbar'])$('#'+id).inert=drawerOpen;$('#overlay').inert=!drawerOpen;photoFocus?.focus({preventScroll:true});};if(reduced()||!photoFocus?.isConnected){finish();return;}const r=photo.getBoundingClientRect(),target=photoFocus.querySelector('img')?.getBoundingClientRect();if(target&&gallery[photoIndex]===photoFocus.dataset.photo){const a=photoAnimate('none',`translate(${target.x+target.width/2-r.x-r.width/2}px,${target.y+target.height/2-r.y-r.height/2}px) scale(${target.width/r.width},${target.height/r.height})`);a?.finished.then(finish,finish);}else finish();}
const pointers=new Map();let startX=0,pinchDistance=0,pinchZoom=1,swipeAllowed=true;
stage.addEventListener('pointerdown',e=>{pointers.set(e.pointerId,[e.clientX,e.clientY]);if(pointers.size===1){startX=e.clientX;swipeAllowed=zoom===1;}if(pointers.size===2){swipeAllowed=false;const [a,b]=[...pointers.values()];pinchDistance=Math.hypot(a[0]-b[0],a[1]-b[1]);pinchZoom=zoom;}});
stage.addEventListener('pointermove',e=>{if(!pointers.has(e.pointerId))return;pointers.set(e.pointerId,[e.clientX,e.clientY]);if(pointers.size===2){const [a,b]=[...pointers.values()];zoom=Math.max(1,Math.min(3,pinchZoom*Math.hypot(a[0]-b[0],a[1]-b[1])/pinchDistance));photo.style.transform=`scale(${zoom})`;}});
stage.addEventListener('pointerup',e=>{if(pointers.size===1&&swipeAllowed&&Math.abs(e.clientX-startX)>55)showPhoto(photoIndex+(e.clientX<startX?1:-1));pointers.delete(e.pointerId);});
stage.addEventListener('pointercancel',e=>pointers.delete(e.pointerId));
stage.addEventListener('dblclick',()=>{zoom=zoom===1?2:1;photo.style.transform=`scale(${zoom})`;});
document.addEventListener('keydown',e=>{if(viewer.hidden)return;if(['Escape','Tab','ArrowRight','ArrowLeft'].includes(e.key))e.stopImmediatePropagation();if(e.key==='Escape'){e.preventDefault();closePhoto();}if(e.key==='ArrowRight')showPhoto(photoIndex+1);if(e.key==='ArrowLeft')showPhoto(photoIndex-1);if(e.key==='Tab'){const buttons=[...viewer.querySelectorAll('button')],first=buttons[0],last=buttons.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus();}}},true);
document.addEventListener('change',e=>{if(e.target.matches('.quick-jump')&&e.target.value){state.day=+e.target.value;state.view='day';render();}});
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.hasAttribute('data-top'))window.scrollTo({top:0,behavior:reduced()?'instant':'smooth'});if(b.hasAttribute('data-enter'))$('#itinerary').scrollIntoView({behavior:reduced()?'instant':'smooth',block:'start'});if(b.hasAttribute('data-expand-day')){const panel=$('#fullDay'),open=!panel.classList.contains('is-open');if(open)expandedDays.add(state.day);else expandedDays.delete(state.day);panel.inert=!open;panel.classList.toggle('is-open',open);b.setAttribute('aria-expanded',String(open));b.innerHTML=(open?'收起详细安排':'展开详细安排')+' <span>⌄</span>';if(open)setupSegments();}if(b.dataset.country){country=b.dataset.country;document.querySelectorAll('[data-country]').forEach(x=>x.setAttribute('aria-pressed',String(x.dataset.country===country)));$('.journal-grid').innerHTML=journalCards();moveSlider($('.country-segments'));animateContent($('.journal-grid'));}if(b.dataset.photo)openPhoto(b.dataset.photo,b.querySelector('img'));if(b.hasAttribute('data-photo-close'))closePhoto();if(b.hasAttribute('data-photo-next'))showPhoto(photoIndex+1);if(b.hasAttribute('data-photo-prev'))showPhoto(photoIndex-1);if(b.hasAttribute('data-share'))shareJournal();if(b.hasAttribute('data-copy-link'))copyLink(location.href);if(b.hasAttribute('data-credits'))openDrawer('照片来源与许可',`<p>优先复用原项目照片。部分旅游机构及运营商照片的转载许可尚需原项目持有人复核。分享封面使用Eric Kilby的CC BY-SA 2.0冰洞照片，已注明裁切与排版。</p><p><a href="share/LICENSE.txt" target="_blank" rel="noopener">分享封面许可</a></p>${Object.entries(CREDITS).map(([k,c])=>`<p><strong>${esc(c.title||k)}</strong><br>${esc(c.author||'来源署名见原页面')} ${esc(c.license||'许可状态待复核')}<br>${c.source?ext(c.source,'查看原始来源',''):''}</p>`).join('')}`);});
/* Drawer photography opens the same viewer without losing the place detail. */
document.addEventListener('click',e=>{const im=e.target.closest('.detail-photo img');if(!im)return;const key=Object.keys(DATA.places).find(k=>pImage(k)===im.getAttribute('src'));if(key)openPhoto(key,im);});
parseRoute();navigatingHistory=true;render(false);navigatingHistory=false;
if(!location.hash)history.replaceState(null,'','#home');
